import{_ as n,a0 as p,w as l,s as f,ao as o,I as r,x as s,a1 as t,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const F=JSON.parse('{"title":"什麼是 Firefox ESR？如何在 Ubuntu 中安裝它？ | LCTT x X-CMD","titleTemplate":false,"description":"什麼是 Firefox ESR？如何在 Ubuntu 中安裝它？ | LCTT (202301) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"什麼是 Firefox ESR？如何在 Ubuntu 中安裝它？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"什麼是 Firefox ESR？如何在 Ubuntu 中安裝它？ | LCTT (202301) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202301/20221201.5 ⭐️⭐️ What is Firefox ESR How to Install it in Ubuntu","title":"什麼是 Firefox ESR？如何在 Ubuntu 中安裝它？","tag":"202301","desc":""},"relativePath":"202301/20221201.5 ⭐️⭐️ What is Firefox ESR How to Install it in Ubuntu.md","filePath":"[post].md"}'),u={name:"202301/20221201.5 ⭐️⭐️ What is Firefox ESR How to Install it in Ubuntu.md"};function d(h,i,g,b,x,k){const e=p("Link");return l(),f("div",null,[i[24]||(i[24]=o('<h1 id="什麼是-firefox-esr-如何在-ubuntu-中安裝它" tabindex="-1">什麼是 Firefox ESR？如何在 Ubuntu 中安裝它？ <a class="header-anchor" href="#什麼是-firefox-esr-如何在-ubuntu-中安裝它" aria-label="Permalink to “什麼是 Firefox ESR？如何在 Ubuntu 中安裝它？”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202301/07/165704ojar9wfkvptwop0w.jpg" alt=""></p><p>Ubuntu 的 Snap 版本你不喜歡？不喜歡每一次 Firefox 的發佈都要不斷地改變東西？如果你重視穩定性而不是功能，你可以試試 Firefox ESR 版本。</p><h3 id="什麼是-firefox-esr" tabindex="-1">什麼是 Firefox ESR？ <a class="header-anchor" href="#什麼是-firefox-esr" aria-label="Permalink to “什麼是 Firefox ESR？”">​</a></h3><p>Firefox ESR 是 Firefox 的特別版，它不一定像普通版那樣每月都有新功能，但它能提供穩定和安全的瀏覽體驗。這適用於企業、組織和機構，在這些地方，穩定性和核心功能比閃亮的新功能更重要。</p><p>可以把 Firefox ESR 看作是 Linux 發行版的長期穩定版本。它們不一定得到全新的功能，但它們會得到定期的安全和維護更新。這給了用户一個熟悉和穩定的環境。</p><h4 id="你為什麼要關心-firefox-esr" tabindex="-1">你為什麼要關心 Firefox ESR？ <a class="header-anchor" href="#你為什麼要關心-firefox-esr" aria-label="Permalink to “你為什麼要關心 Firefox ESR？”">​</a></h4><p>Firefox 幾乎每個月都會發佈一個新版本。它包含安全和功能更新。</p><p>但有些人可能不喜歡各種功能的加入和刪除。如果在更新之後，你一直想知道某些設置到哪裏去了，或者不喜歡與以前不同的東西，Firefox ESR 可能值得一試。</p><p>基本上，如果你更看重穩定性而不是新功能，那麼 Firefox ESR 就適合你。這也是 Debian 中攜帶的 Firefox 版本，Debian 以其是市場上最穩定的發行版之一而聞名。</p><p>讓我告訴你如何在 Ubuntu 上獲得 Firefox ESR。<strong>你可以同時安裝 Firefox 和 Firefox-ESR 兩個版本。它們的標識沒有視覺上的區別，所以你必須注意你打開的是哪個火狐版本。</strong></p><h3 id="在-ubuntu-中安裝-firefox-esr" tabindex="-1">在 Ubuntu 中安裝 Firefox ESR <a class="header-anchor" href="#在-ubuntu-中安裝-firefox-esr" aria-label="Permalink to “在 Ubuntu 中安裝 Firefox ESR”">​</a></h3><p>在進入安裝之前，讓我來分享一下普通 Firefox 和 Firefox-ESR 之間的版本差異是什麼。在寫這篇文章的時候：</p><ul><li>Firefox 的版本是 <strong>107.0-2</strong>。</li><li>Firefox-ESR 目前的版本是 <strong>102.5.0esr</strong>。</li></ul><p>所以，如果這對你來説沒問題，讓我們看看第一個方法。</p><h4 id="方法-1-使用-ppa-安裝-firefox-esr" tabindex="-1">方法 1：使用 PPA 安裝 Firefox-ESR <a class="header-anchor" href="#方法-1-使用-ppa-安裝-firefox-esr" aria-label="Permalink to “方法 1：使用 PPA 安裝 Firefox-ESR”">​</a></h4><p>Firefox-ESR 在 Ubuntu 的默認倉庫中是不可用的，所以你可以使用 PPA。</p><p>PPA 只不過是一個由個別技術人員或開發者維護的倉庫，擁有默認倉庫所沒有的東西。</p>',18)),r("p",null,[i[1]||(i[1]=s("如果你想了解更多關於 PPA 的信息，我建議你查看我們的其他指南，其中解釋了 ",-1)),t(e,{href:"https://itsfoss.com/ppa-guide/"},{default:a(()=>[...i[0]||(i[0]=[s("如何在 Linux 上使用 PPA",-1)])]),_:1}),i[2]||(i[2]=s("。",-1))]),i[25]||(i[25]=o('<p>打開你的終端，使用給定的命令來添加 Firefox-ESR 的 PPA：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo add-apt-repository ppa:mozillateam/ppa</span></span></code></pre></div><p>然後按回車鍵確認你要添加 PPA：</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/add-firefox-esr-repository-in-ubuntu.png" alt="add firefox esr repository in ubuntu"></p><p>完成後，你需要更新 Ubuntu 中的倉庫索引，以便從這些變化中生效：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update</span></span></code></pre></div><p>現在，你可以通過使用給定的命令來安裝 Firefox-ESR：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install firefox-esr</span></span></code></pre></div><p>接下來，你可以使用給定的命令來檢查你係統中 Firefox-ESR 的安裝版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>firefox-esr -v</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/check-installed-version-of-firefox-esr-in-ubuntu.png" alt="check installed version of firefox esr in ubuntu"></p><p>如何從 Ubuntu 卸載 Firefox-ESR？</p><p>如果 ESR 對你的工作來説感覺太過時了，或者由於其他原因你想從你的系統中刪除它，你可以按照以下步驟刪除 Firefox-ESR 包和倉庫。</p><p>首先，讓我們用下面的方法刪除 Firefox-ESR 包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt remove firefox-esr</span></span></code></pre></div>',15)),r("p",null,[i[4]||(i[4]=s("現在，你可以使用給定的命令來 ",-1)),t(e,{href:"https://itsfoss.com/how-to-remove-or-delete-ppas-quick-tip/"},{default:a(()=>[...i[3]||(i[3]=[s("從 Ubuntu 刪除 PPA",-1)])]),_:1}),i[5]||(i[5]=s("：",-1))]),i[26]||(i[26]=o('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo add-apt-repository --remove ppa:mozillateam/ppa</span></span></code></pre></div><p>這就完成了！</p><h4 id="方法-2-使用-snap-安裝-firefox-esr" tabindex="-1">方法 2：使用 Snap 安裝 Firefox-ESR <a class="header-anchor" href="#方法-2-使用-snap-安裝-firefox-esr" aria-label="Permalink to “方法 2：使用 Snap 安裝 Firefox-ESR”">​</a></h4><p>不管你愛不愛它，Snap 在 Ubuntu 上是預先配置好的，我發現使用 Snap 是安裝軟件包的一個很好的方法，特別是當你想避免從源碼構建它們或使用 PPA 時。</p><p>使用 Snap 安裝 Firefox-ESR，你需要做的就是使用給定的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo snap install firefox --channel=esr/stable</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/install-firefox-esr-using-snaps-in-ubuntu.png" alt="install firefox esr using snaps in ubuntu"></p><p>如何刪除 Firefox-ESR Snap？</p>',8)),r("p",null,[i[7]||(i[7]=s("要刪除 Firefox-ESR（snap 包），請使用 ",-1)),t(e,{href:"https://itsfoss.com/remove-snap/"},{default:a(()=>[...i[6]||(i[6]=[s("snap remove 命令",-1)])]),_:1}),i[8]||(i[8]=s("：",-1))]),i[27]||(i[27]=o('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo snap remove firefox</span></span></code></pre></div><p>這就完成了！</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>我在本指南中解釋瞭如何使用多種方法在 Ubuntu 中安裝 Firefox-ESR。我個人使用 Firefox-ESR 而不是普通版本，因為我有隨機崩潰的情況。</p><p>自從我改用 Firefox-ESR 後，一切都變得穩如磐石。如果你也有同樣的問題，你應該試一試。</p><hr>',6)),r("p",null,[i[10]||(i[10]=s("via: ",-1)),t(e,{href:"https://itsfoss.com/firefox-esr-ubuntu/"},{default:a(()=>[...i[9]||(i[9]=[s("https://itsfoss.com/firefox-esr-ubuntu/",-1)])]),_:1})]),r("p",null,[i[15]||(i[15]=s("作者：",-1)),t(e,{href:"https://itsfoss.com/author/sagar/"},{default:a(()=>[...i[11]||(i[11]=[s("Sagar Sharma",-1)])]),_:1}),i[16]||(i[16]=s(" 選題：",-1)),t(e,{href:"https://github.com/lkxed"},{default:a(()=>[...i[12]||(i[12]=[s("lkxed",-1)])]),_:1}),i[17]||(i[17]=s(" 譯者：",-1)),t(e,{href:"https://github.com/geekpi"},{default:a(()=>[...i[13]||(i[13]=[s("geekpi",-1)])]),_:1}),i[18]||(i[18]=s(" 校對：",-1)),t(e,{href:"https://github.com/wxy"},{default:a(()=>[...i[14]||(i[14]=[s("wxy",-1)])]),_:1})]),r("p",null,[i[21]||(i[21]=s("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...i[19]||(i[19]=[s("LCTT",-1)])]),_:1}),i[22]||(i[22]=s(" 原創編譯，",-1)),t(e,{href:"https://linux.cn/"},{default:a(()=>[...i[20]||(i[20]=[s("Linux中國",-1)])]),_:1}),i[23]||(i[23]=s(" 榮譽推出",-1))])])}const E=n(u,[["render",d]]);export{F as __pageData,E as default};
